const assert = require('node:assert/strict');
const H = require('../js/selection-handoff.js');
const A = require('../js/prototype-selection-handoff.js');
const fs = require('node:fs'), path = require('node:path'), vm = require('node:vm');
const project = { projectId: 'p1', code: 'P1' };
const unit = { unitId: 'u1', no: 'AHU-1', designConditions: { cabinetWidth: { value: 2000 }, cabinetHeight: { value: 1800 } } };
const segment = { id: 's1', type: 'medium', sourceType: 'medium', interface: {} };
const context = A.begin(project, unit, segment, 'n1');
assert.equal(context.target.segmentType, 'medium-filter');
assert.deepEqual(A.dimensions(unit), { width: 2000, height: 1800 });
assert.throws(() => A.dimensions({ designConditions: {} }), /真实箱体/);
assert.throws(() => A.toFormal(project, unit, { id: 's2', type: 'medium', sourceType: 'primary-filter' }), /不匹配/);
assert.equal(H.fingerprint(context.workbenchSnapshot), context.workbenchFingerprint);
const sandbox = { window: {}, document: { addEventListener() {} }, console };
vm.createContext(sandbox);
const moduleRoot = path.resolve(__dirname, '../../01-过滤器选型');
vm.runInContext(fs.readFileSync(path.join(moduleRoot, 'data/filter-database.js'), 'utf8'), sandbox);
vm.runInContext(fs.readFileSync(path.join(moduleRoot, 'js/filter-selector.js'), 'utf8'), sandbox);
const database = sandbox.window.FilterDatabase, arrangement = sandbox.window.FilterSelector.calculate('pull', 20, 18), type = database.filterTypes.find(item => item.id === 'f_300');
let hash = 2166136261;
for (const char of JSON.stringify(database)) { hash ^= char.charCodeAt(0); hash = Math.imul(hash, 16777619); }
const result = { selector: 'filter', status: 'selected', model: 'F300 标准排布', source: '过滤器专业数据库', rule: { id: 'filter-standard-arrangement', version: database.version + '+' + (hash >>> 0).toString(16).padStart(8, '0') }, target: context.target, workbenchSnapshot: context.workbenchSnapshot, workbenchFingerprint: context.workbenchFingerprint, input: { mode: 'pull', typeId: type.id, widthModule: 20, heightModule: 18, widthMm: 2000, heightMm: 1800 }, data: { filterType: type, arrangement: { mode: 'pull', width: arrangement.widths, height: arrangement.heights, specifications: arrangement.specifications, total: arrangement.total } }, warnings: ['阻力需要复核'] };
const message = JSON.parse(JSON.stringify({ protocol: 'p001-selection-result-v1', nonce: 'n1', result }));
let verified = A.verify(project, unit, segment, context, message, { filterDatabase: database });
assert.equal(verified.ok, true, verified.reason);
assert.equal(A.apply(verified), true);
const reopened = JSON.parse(JSON.stringify(segment));
assert.equal(reopened.model, result.model);
assert.equal(reopened.selectionLevel, 'L2');
assert.equal(reopened.interface.output.automatedSelection.result.arrangement.total, 12);
assert.equal(reopened.confirmed, false, '选型通过不等于整段工程复核通过');
assert.equal(A.verify(project, { ...unit, designConditions: { ...unit.designConditions, cabinetWidth: { value: 2100 } } }, segment, context, message, { filterDatabase: database }).ok, false);
assert.equal(A.verify(project, { ...unit, unitId: 'other-unit' }, segment, context, message, { filterDatabase: database }).ok, false);
assert.equal(A.verify(project, unit, undefined, context, message, { filterDatabase: database }).ok, false);
assert.equal(A.verify(project, unit, segment, context, { ...message, nonce: 'other' }, { filterDatabase: database }).ok, false);
const tampered = structuredClone(message); tampered.result.data.arrangement.total++;
assert.equal(A.verify(project, unit, segment, context, tampered, { filterDatabase: database }).ok, false);
const otherDB = JSON.parse(JSON.stringify(database)); otherDB.filterTypes[0].detail += 'modified';
assert.equal(A.verify(project, unit, segment, context, message, { filterDatabase: otherDB }).ok, false);
assert.equal(A.invalidate(reopened, '真实截面修改'), true);
assert.equal(reopened.selectionLevel, 'L1');
assert.equal(reopened.interface.selection.professionalResult, undefined);
assert.equal(reopened.professionalHistory.length, 1);
assert.equal(A.invalidate(reopened, '再次修改'), false, '不重复归档已失效记录');
assert.throws(() => A.begin(project, { ...unit, designConditions: { cabinetWidth: { value: 2050 }, cabinetHeight: { value: 1800 } } }, segment, 'x'), /600–3300/);
const legacy = [{ code: 'OLD', units: [{ no: 'A', segments: [] }] }]; A.ensureIds(legacy);
const identities = [legacy[0].projectId, legacy[0].units[0].unitId]; A.ensureIds(legacy);
assert.deepEqual([legacy[0].projectId, legacy[0].units[0].unitId], identities);
console.log('通过：原型过滤器真实规则复用、JSON回传/应用/重开、真实尺寸、稳定ID、错段/输入变更/数据库变更拒收与L2失效留档。');
